    /** 현재 시각 전후 1시간이 유효기간인 쿠폰 JSON. maxDiscountAmount가 null이면 생략(제한 없음). */
    protected static String couponJson(String code, String type, long value, long minOrderAmount, Long maxDiscountAmount,
