30	/** RFC 9457 Problem Details. 모든 오류 응답은 application/problem+json + code 필드를 갖는다. */
31	@RestControllerAdvice
32	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
33	
34	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
35	
36	    // ---- 도메인 예외 ----
37	
38	    @ExceptionHandler(BusinessException.class)
39	    ResponseEntity<Object> handleBusiness(BusinessException ex, HttpServletRequest request) {
40	        List<FieldIssue> errors = ex instanceof RequestValidationException rve ? rve.getErrors() : List.of();
41	        return problem(ex.getCode().status(), ex.getCode(), ex.getMessage(), HttpHeaders.EMPTY, request.getRequestURI(), errors);
42	    }
43	
44	    @ExceptionHandler(ConstraintViolationException.class)
45	    ResponseEntity<Object> handleConstraintViolation(ConstraintViolationException ex, HttpServletRequest request) {
46	        List<FieldIssue> errors = ex.getConstraintViolations().stream()
47	                .map(v -> new FieldIssue(v.getPropertyPath().toString(), v.getMessage()))
48	                .toList();
49	        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 값이 올바르지 않습니다",
50	                HttpHeaders.EMPTY, request.getRequestURI(), errors);
51	    }
52	
53	    @ExceptionHandler(DataIntegrityViolationException.class)
54	    ResponseEntity<Object> handleDataIntegrity(DataIntegrityViolationException ex, HttpServletRequest request) {
55	        String chain = causeMessages(ex);
56	        String uri = request.getRequestURI();
57	        if (chain.contains("uk_coupons_code")) {
58	            return businessProblem(ErrorCode.DUPLICATE_COUPON_CODE, "이미 존재하는 쿠폰 코드입니다", uri);
59	        }
60	        if (chain.contains("ux_orders_active_coupon_user")) {
61	            return businessProblem(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다", uri);
62	        }
63	        if (chain.contains("ck_products_reserved_range")) {
64	            return businessProblem(ErrorCode.INSUFFICIENT_STOCK, "주문 가능 수량이 부족합니다", uri);
65	        }
66	        if (chain.contains("ck_coupons_used_count")) {
67	            return businessProblem(ErrorCode.COUPON_EXHAUSTED, "쿠폰이 모두 소진되었습니다", uri);
68	        }
69	        log.error("Unmapped data integrity violation", ex);
70	        return internal(uri);
71	    }
72	
73	    @ExceptionHandler(Exception.class)
74	    ResponseEntity<Object> handleUnexpected(Exception ex, HttpServletRequest request) {
75	        log.error("Unexpected error on {}", request.getRequestURI(), ex);
76	        return internal(request.getRequestURI());
77	    }
78	
79	    // ---- 프레임워크(MVC) 예외: 모두 code를 붙인다 ----
80	
81	    @Override
82	    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
83	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
84	        List<FieldIssue> errors = new ArrayList<>();
85	        for (FieldError fe : ex.getBindingResult().getFieldErrors()) {
86	            errors.add(new FieldIssue(fe.getField(), fe.getDefaultMessage()));
87	        }
88	        for (ObjectError oe : ex.getBindingResult().getGlobalErrors()) {
89	            errors.add(new FieldIssue(oe.getObjectName(), oe.getDefaultMessage()));
90	        }
91	        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 값이 올바르지 않습니다",
92	                headers, path(request), errors);
93	    }
94	
95	    @Override
96	    protected ResponseEntity<Object> handleHandlerMethodValidationException(HandlerMethodValidationException ex,
97	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
98	        List<FieldIssue> errors = new ArrayList<>();
99	        ex.getParameterValidationResults().forEach(r -> r.getResolvableErrors().forEach(e ->
100	                errors.add(new FieldIssue(String.valueOf(r.getMethodParameter().getParameterName()), e.getDefaultMessage()))));
101	        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 값이 올바르지 않습니다",
102	                headers, path(request), errors);
103	    }
104	
105	    @Override
106	    protected ResponseEntity<Object> handleHttpMessageNotReadable(HttpMessageNotReadableException ex,
107	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
108	        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 본문을 해석할 수 없습니다",
109	                headers, path(request), List.of(new FieldIssue("body", "올바른 JSON 형식과 타입이어야 합니다")));
110	    }
111	
112	    /** 415는 R11.3 표 밖이므로 400으로 매핑한다 (01 설계 11.2). */
113	    @Override
114	    protected ResponseEntity<Object> handleHttpMediaTypeNotSupported(HttpMediaTypeNotSupportedException ex,
115	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
116	        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "지원하지 않는 Content-Type 입니다",
117	                HttpHeaders.EMPTY, path(request), List.of(new FieldIssue("header:Content-Type", "application/json 이어야 합니다")));
118	    }
119	
120	    @Override
121	    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, Object body, HttpHeaders headers,
122	            HttpStatusCode statusCode, WebRequest request) {
123	        HttpStatus status = HttpStatus.resolve(statusCode.value());
124	        ErrorCode code = status == null ? ErrorCode.INTERNAL_ERROR : switch (status) {
125	            case BAD_REQUEST -> ErrorCode.VALIDATION_ERROR;
126	            case NOT_FOUND -> ErrorCode.RESOURCE_NOT_FOUND;
127	            case METHOD_NOT_ALLOWED -> ErrorCode.METHOD_NOT_ALLOWED;
128	            case NOT_ACCEPTABLE -> ErrorCode.NOT_ACCEPTABLE;
129	            default -> statusCode.is4xxClientError() ? ErrorCode.VALIDATION_ERROR : ErrorCode.INTERNAL_ERROR;
130	        };
131	        if (code == ErrorCode.INTERNAL_ERROR) {
132	            log.error("Framework error", ex);
133	            return internal(path(request));
134	        }
135	        String detail = body instanceof ProblemDetail pd && pd.getDetail() != null ? pd.getDetail() : code.title();
136	        return problem(statusCode, code, detail, headers, path(request), List.of());
137	    }
138	
139	    // ---- 조립 ----
140	
141	    private ResponseEntity<Object> businessProblem(ErrorCode code, String detail, String uri) {
142	        return problem(code.status(), code, detail, HttpHeaders.EMPTY, uri, List.of());
143	    }
144	
145	    private ResponseEntity<Object> internal(String uri) {
146	        return problem(HttpStatus.INTERNAL_SERVER_ERROR, ErrorCode.INTERNAL_ERROR,
147	                "서버 내부 오류가 발생했습니다", HttpHeaders.EMPTY, uri, List.of());
148	    }
149	
150	    private ResponseEntity<Object> problem(HttpStatusCode status, ErrorCode code, String detail, HttpHeaders headers,
151	            String uri, List<FieldIssue> errors) {
152	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
153	        pd.setType(URI.create(code.typeUri()));
154	        pd.setTitle(code.title());
155	        pd.setProperty("code", code.name());
156	        if (uri != null) {
157	            try {
158	                pd.setInstance(URI.create(uri));
159	            } catch (IllegalArgumentException ignored) {
160	                // instance는 선택 필드
161	            }
162	        }
163	        if (errors != null && !errors.isEmpty()) {
164	            pd.setProperty("errors", errors);
165	        }
166	        HttpHeaders out = new HttpHeaders();
167	        if (headers != null) {
168	            out.putAll(headers);
169	        }
170	        out.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
171	        return new ResponseEntity<>(pd, out, status);
172	    }
173	
174	    private static String path(WebRequest request) {
175	        return request instanceof ServletWebRequest swr ? swr.getRequest().getRequestURI() : null;
176	    }
177	
178	    private static String causeMessages(Throwable ex) {
179	        StringBuilder sb = new StringBuilder();
180	        for (Throwable t = ex; t != null; t = t.getCause()) {
181	            if (t.getMessage() != null) {
182	                sb.append(t.getMessage()).append('\n');
183	            }
184	            if (t.getCause() == t) {
185	                break;
186	            }
187	        }
188	        return sb.toString();
189	    }
190	}
