14	    @Bean
15	    Jackson2ObjectMapperBuilderCustomizer strictCoercionCustomizer() {
16	        return builder -> builder.postConfigurer(mapper -> {
17	            // 문자열 필드에 숫자/불리언 금지
18	            mapper.coercionConfigFor(LogicalType.Textual)
19	                    .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail)
20	                    .setCoercion(CoercionInputShape.Float, CoercionAction.Fail)
21	                    .setCoercion(CoercionInputShape.Boolean, CoercionAction.Fail);
22	            // 숫자/불리언 필드에 문자열(빈 문자열 포함) 금지
23	            for (LogicalType type : new LogicalType[] {LogicalType.Integer, LogicalType.Float, LogicalType.Boolean}) {
24	                mapper.coercionConfigFor(type)
25	                        .setCoercion(CoercionInputShape.String, CoercionAction.Fail)
26	                        .setCoercion(CoercionInputShape.EmptyString, CoercionAction.Fail);
27	            }
28	            // 정수 필드에 소수 금지
29	            mapper.coercionConfigFor(LogicalType.Integer).setCoercion(CoercionInputShape.Float, CoercionAction.Fail);
