18	        return instant == null ? null : OffsetDateTime.ofInstant(instant, ZoneOffset.UTC);
19	    }
20	
21	    /** 오프셋이 반드시 있는 ISO-8601 문자열을 µs 정밀도의 Instant로 변환. 실패하면 400. */
22	    public static Instant parseOffsetDateTime(String field, String value) {
23	        try {
24	            return OffsetDateTime.parse(value, DateTimeFormatter.ISO_OFFSET_DATE_TIME)
25	                    .toInstant().truncatedTo(ChronoUnit.MICROS);
26	        } catch (DateTimeParseException e) {
27	            throw new RequestValidationException(field, "오프셋이 포함된 ISO-8601 시각이어야 합니다");
28	        }
29	    }
