13	@Entity
14	@Table(name = "coupons")
15	public class Coupon {
16	
17	    @Id
18	    @GeneratedValue(strategy = GenerationType.IDENTITY)
19	    private Long id;
20	
21	    @Column(name = "code", nullable = false, length = 20, updatable = false)
22	    private String code;
23	
24	    @Enumerated(EnumType.STRING)
25	    @Column(name = "discount_type", nullable = false, length = 10)
26	    private CouponType type;
27	
28	    @Column(name = "discount_value", nullable = false)
29	    private long value;
30	
31	    @Column(name = "min_order_amount", nullable = false)
32	    private long minOrderAmount;
33	
34	    @Column(name = "max_discount_amount")
35	    private Long maxDiscountAmount;
36	
37	    @Column(name = "total_quantity", nullable = false)
38	    private long totalQuantity;
39	
40	    @Column(name = "used_count", nullable = false)
41	    private long usedCount;
42	
43	    @Column(name = "valid_from", nullable = false)
44	    private Instant validFrom;
45	
46	    @Column(name = "valid_until", nullable = false)
47	    private Instant validUntil;
48	
49	    @Column(name = "created_at", nullable = false, updatable = false)
50	    private Instant createdAt;
51	
52	    protected Coupon() {
53	    }
54	
55	    public Coupon(String code, CouponType type, long value, long minOrderAmount, Long maxDiscountAmount,
56	            long totalQuantity, Instant validFrom, Instant validUntil, Instant createdAt) {
57	        this.code = code;
58	        this.type = type;
59	        this.value = value;
60	        this.minOrderAmount = minOrderAmount;
61	        this.maxDiscountAmount = maxDiscountAmount;
62	        this.totalQuantity = totalQuantity;
63	        this.usedCount = 0;
64	        this.validFrom = validFrom;
65	        this.validUntil = validUntil;
66	        this.createdAt = createdAt;
67	    }
68	
69	    /** validFrom 이상, validUntil 미만 */
70	    public boolean isValidAt(Instant now) {
71	        return !now.isBefore(validFrom) && now.isBefore(validUntil);
72	    }
73	
74	    /** R2.4: FIXED=value, RATE=floor(subtotal*value/100) -> maxDiscountAmount 상한 -> subtotal 상한 */
75	    public long calculateDiscount(long subtotal) {
76	        long discount = type == CouponType.FIXED ? value : Math.multiplyExact(subtotal, value) / 100;
77	        if (maxDiscountAmount != null) {
78	            discount = Math.min(discount, maxDiscountAmount);
79	        }
80	        return Math.min(discount, subtotal);
81	    }
