11	import java.time.temporal.ChronoUnit;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	@Service
16	public class CouponService {
17	
18	    private final CouponRepository couponRepository;
19	    private final Clock clock;
20	
21	    public CouponService(CouponRepository couponRepository, Clock clock) {
22	        this.couponRepository = couponRepository;
23	        this.clock = clock;
24	    }
25	
26	    @Transactional
27	    public CouponResponse create(CreateCouponRequest request) {
28	        // 단일 필드 검증(Bean Validation)이 모두 통과한 뒤의 교차 검증. 모두 400.
29	        CouponType type = CouponType.valueOf(request.type());
30	        if (type == CouponType.RATE && request.value() > 100) {
31	            throw new RequestValidationException("value", "RATE 쿠폰의 value는 1~100 이어야 합니다");
32	        }
33	        Instant validFrom = TimeFormats.parseOffsetDateTime("validFrom", request.validFrom());
34	        Instant validUntil = TimeFormats.parseOffsetDateTime("validUntil", request.validUntil());
35	        if (!validFrom.isBefore(validUntil)) {
36	            throw new RequestValidationException("validUntil", "validFrom 보다 이후여야 합니다");
37	        }
38	        if (couponRepository.existsByCode(request.code())) {
39	            throw new DuplicateCouponCodeException("이미 존재하는 쿠폰 코드입니다: " + request.code());
40	        }
41	        Coupon coupon = new Coupon(request.code(), type, request.value(),
42	                request.minOrderAmount() == null ? 0L : request.minOrderAmount(),
43	                request.maxDiscountAmount(), request.totalQuantity(), validFrom, validUntil,
44	                clock.instant().truncatedTo(ChronoUnit.MICROS));
45	        // 동시 등록 경합은 uk_coupons_code 위반으로 드러나며 핸들러가 409로 매핑한다.
46	        return CouponResponse.from(couponRepository.saveAndFlush(coupon));
47	    }
48	
49	    @Transactional(readOnly = true)
50	    public CouponResponse get(String code) {
51	        return couponRepository.findByCode(code)
52	                .map(CouponResponse::from)
53	                .orElseThrow(() -> new CouponNotFoundException("쿠폰 " + code + "을(를) 찾을 수 없습니다."));
54	    }
55	}
