40	            @RequestHeader(value = RequestHeaders.USER_ID, required = false) String userId,
41	            @RequestHeader(value = RequestHeaders.IDEMPOTENCY_KEY, required = false) String idempotencyKey,
42	            @Valid @RequestBody CreateOrderRequest request) {
43	        RequestHeaders.requireUserId(userId);
44	        RequestHeaders.requireIdempotencyKey(idempotencyKey);
45	        rejectDuplicateProducts(request);
46	        if (request.couponCode() != null && request.couponCode().isBlank()) {
