57	    @GetMapping
58	    public OrderPageResponse list(
59	            @RequestParam(required = false) String userId,
60	            @RequestParam(required = false) String status,
61	            @RequestParam(required = false) String size,
62	            @RequestParam(required = false) String cursor) {
63	        if (userId != null && (userId.isBlank() || userId.length() > 50)) {
64	            throw new RequestValidationException("query:userId", "공백이 아닌 1~50자여야 합니다");
65	        }
66	        OrderStatus statusFilter = null;
67	        if (status != null) {
68	            try {
69	                statusFilter = OrderStatus.valueOf(status);
70	            } catch (IllegalArgumentException e) {
71	                throw new RequestValidationException("query:status", "정의되지 않은 상태입니다: " + status);
72	            }
73	        }
74	        int pageSize = 20;
75	        if (size != null) {
76	            try {
77	                pageSize = Integer.parseInt(size);
78	            } catch (NumberFormatException e) {
79	                throw new RequestValidationException("query:size", "정수여야 합니다");
80	            }
81	            if (pageSize < 1 || pageSize > 100) {
82	                throw new RequestValidationException("query:size", "1~100 이어야 합니다");
83	            }
84	        }
