36	        List<Order> page = hasNext ? rows.subList(0, size) : rows;
37	        List<OrderResponse> content = page.stream().map(OrderResponse::from).toList();
38	        String nextCursor = hasNext ? OrderCursor.of(page.get(page.size() - 1)).encode() : null;
39	        return new OrderPageResponse(content, nextCursor);
40	    }
