28	import java.time.Instant;
29	import java.time.temporal.ChronoUnit;
30	import java.util.ArrayList;
31	import java.util.List;
32	import java.util.Map;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.stereotype.Service;
35	import org.springframework.transaction.support.TransactionTemplate;
36	
37	/**
38	 * 멱등 키 / PG 호출 / 커밋 후 오류 응답(402)이 얽힌 쓰기 흐름. 트랜잭션 경계를 TransactionTemplate으로 명시한다.
39	 * 이 클래스 자체에는 트랜잭션이 없고, 멱등 begin/abandon은 각자 짧게 커밋된다 (01 설계 6.4, 10.3).
40	 */
41	@Service
42	public class OrderCommandService {
43	
44	    private final OrderRepository orderRepository;
45	    private final ProductRepository productRepository;
46	    private final CouponRepository couponRepository;
47	    private final OrderEffects effects;
48	    private final IdempotencyService idempotency;
49	    private final PaymentGatewayClient gateway;
50	    private final OrderProperties properties;
51	    private final Clock clock;
52	    private final ObjectMapper objectMapper;
53	    private final TransactionTemplate tx;
54	
55	    public OrderCommandService(OrderRepository orderRepository, ProductRepository productRepository,
56	            CouponRepository couponRepository, OrderEffects effects, IdempotencyService idempotency,
57	            PaymentGatewayClient gateway, OrderProperties properties, Clock clock, ObjectMapper objectMapper,
58	            TransactionTemplate tx) {
59	        this.orderRepository = orderRepository;
60	        this.productRepository = productRepository;
61	        this.couponRepository = couponRepository;
62	        this.effects = effects;
63	        this.idempotency = idempotency;
64	        this.gateway = gateway;
65	        this.properties = properties;
66	        this.clock = clock;
67	        this.objectMapper = objectMapper;
68	        this.tx = tx;
69	    }
70	
71	    private Instant now() {
72	        return clock.instant().truncatedTo(ChronoUnit.MICROS);
73	    }
74	
75	    // =====================================================================
76	    // E5. 주문 생성
77	    // =====================================================================
78	
79	    public IdempotentResponse create(String userId, String idempotencyKey, CreateOrderRequest request) {
80	        String fingerprint = RequestFingerprint.of(IdempotencyScope.ORDER_CREATE, "/api/orders", userId, json(request));
81	        Begin begin = idempotency.begin(IdempotencyScope.ORDER_CREATE, idempotencyKey, fingerprint);
82	        if (begin.replay() != null) {
83	            return begin.replay();
84	        }
85	        long recordId = begin.recordId();
86	        try {
87	            return tx.execute(status -> doCreate(recordId, userId, request));
88	        } catch (RuntimeException e) {
89	            idempotency.abandon(recordId);
90	            throw e;
91	        }
92	    }
93	
94	    private IdempotentResponse doCreate(long recordId, String userId, CreateOrderRequest request) {
95	        Instant now = now();
96	
97	        // 404: 상품(id 오름차순 락) -> 쿠폰(락)
98	        Map<Long, Product> products = effects.lockProducts(request.items().stream().map(CreateOrderRequest.Item::productId).toList());
99	        Coupon coupon = null;
100	        if (request.couponCode() != null) {
101	            if (request.couponCode().isBlank()) {
102	                throw new CouponNotFoundException("쿠폰 " + request.couponCode() + "을(를) 찾을 수 없습니다.");
103	            }
104	            coupon = couponRepository.findByCodeForUpdate(request.couponCode())
105	                    .orElseThrow(() -> new CouponNotFoundException("쿠폰 " + request.couponCode() + "을(를) 찾을 수 없습니다."));
106	        }
107	
108	        // 409 재고
109	        for (CreateOrderRequest.Item item : request.items()) {
110	            Product p = products.get(item.productId());
111	            if (p.available() < item.quantity()) {
112	                throw new InsufficientStockException("상품 " + p.getId() + "의 주문 가능 수량(" + p.available()
113	                        + ")이 요청 수량(" + item.quantity() + ")보다 적습니다.");
114	            }
115	        }
116	
117	        long subtotal = 0;
118	        List<OrderLine> lines = new ArrayList<>();
119	        for (CreateOrderRequest.Item item : request.items()) {
120	            Product p = products.get(item.productId());
121	            lines.add(new OrderLine(p.getId(), item.quantity(), p.getPrice()));
122	            subtotal = Math.addExact(subtotal, Math.multiplyExact(p.getPrice(), (long) item.quantity()));
123	        }
124	
125	        // 409 쿠폰: 적용 불가(a 유효기간, b 최소금액, c 사용자 중복) -> 소진(d)
126	        long discount = 0;
127	        if (coupon != null) {
128	            if (!coupon.isValidAt(now)) {
129	                throw new CouponNotApplicableException("쿠폰 " + coupon.getCode() + "의 유효기간이 아닙니다.");
130	            }
131	            if (subtotal < coupon.getMinOrderAmount()) {
132	                throw new CouponNotApplicableException("주문 금액이 쿠폰 최소 주문 금액(" + coupon.getMinOrderAmount() + ")보다 적습니다.");
133	            }
134	            if (orderRepository.existsActiveCouponUse(coupon.getCode(), userId)) {
135	                throw new CouponNotApplicableException("이미 이 쿠폰을 사용 중인 주문이 있습니다.");
136	            }
137	            if (coupon.isExhausted()) {
138	                throw new CouponExhaustedException("쿠폰 " + coupon.getCode() + "이(가) 모두 소진되었습니다.");
139	            }
140	            discount = coupon.calculateDiscount(subtotal);
141	        }
142	
143	        // 반영 (한 트랜잭션: 부분 반영 없음)
144	        for (CreateOrderRequest.Item item : request.items()) {
145	            products.get(item.productId()).reserve(item.quantity());
146	        }
147	        if (coupon != null) {
148	            coupon.use();
149	        }
150	        Order order = new Order(userId, coupon == null ? null : coupon.getCode(), lines, subtotal, discount,
151	                now, now.plus(properties.paymentTtl()));
152	        orderRepository.saveAndFlush(order);
153	
154	        IdempotentResponse response = new IdempotentResponse(HttpStatus.CREATED.value(),
155	                json(OrderResponse.from(order)), "/api/orders/" + order.getId());
156	        idempotency.complete(recordId, response);
157	        return response;
158	    }
159	
160	    // =====================================================================
161	    // E8. 결제
162	    // =====================================================================
163	
164	    private record PayOutcome(boolean declined, IdempotentResponse response) {
165	    }
166	
167	    public IdempotentResponse pay(long orderId, String idempotencyKey, String userIdHeader, PayRequest request) {
168	        String fingerprint = RequestFingerprint.of(IdempotencyScope.ORDER_PAY, "/api/orders/" + orderId + "/pay",
169	                userIdHeader, json(request));
170	        Begin begin = idempotency.begin(IdempotencyScope.ORDER_PAY, idempotencyKey, fingerprint);
171	        if (begin.replay() != null) {
172	            return begin.replay();
173	        }
174	        long recordId = begin.recordId();
175	        PayOutcome outcome;
176	        try {
177	            outcome = tx.execute(status -> doPay(recordId, orderId, idempotencyKey, request));
178	        } catch (RuntimeException e) {
179	            idempotency.abandon(recordId);
180	            throw e;
181	        }
182	        if (outcome.declined()) {
183	            // 상태 변경은 커밋되었다. 비2xx이므로 키는 저장하지 않는다 (R4.4).
184	            idempotency.abandon(recordId);
185	            throw new PaymentDeclinedException("결제가 거절되었습니다.");
186	        }
187	        return outcome.response();
188	    }
189	
190	    private PayOutcome doPay(long recordId, long orderId, String idempotencyKey, PayRequest request) {
191	        // 이 트랜잭션에서 주문에 대한 첫 접근이 FOR UPDATE 이어야 한다.
192	        Order order = orderRepository.findByIdForUpdate(orderId)
193	                .orElseThrow(() -> new OrderNotFoundException("주문 " + orderId + "을(를) 찾을 수 없습니다."));
194	        Instant now = now();
195	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT || order.isExpiredAt(now)) {
196	            throw new InvalidOrderStateException("주문 " + orderId + "은(는) 결제할 수 없는 상태입니다: " + order.getStatus());
197	        }
198	
199	        boolean approved = true;
200	        String paymentId = null;
201	        if (order.getTotalPrice() > 0) { // R5.7: 0원이면 PG 없이 바로 승인
202	            // 주문 행 락을 쥔 채 호출한다 (R10.5). 장애면 예외 -> 롤백 (주문/재고/쿠폰 불변).
203	            PaymentResult result = gateway.pay(idempotencyKey, orderId, order.getTotalPrice(), request.cardToken());
204	            approved = result.approved();
205	            paymentId = result.paymentId();
206	        }
207	
208	        if (approved) {
209	            effects.confirmSale(order);
210	            order.markPaid(now(), paymentId);
211	            IdempotentResponse response = new IdempotentResponse(HttpStatus.OK.value(), json(OrderResponse.from(order)), null);
212	            idempotency.complete(recordId, response);
213	            return new PayOutcome(false, response);
214	        }
215	        effects.releaseReservation(order);
216	        effects.releaseCoupon(order);
217	        order.markPaymentFailed(now(), paymentId);
218	        return new PayOutcome(true, null);
219	    }
220	
221	    // =====================================================================
222	    // E9. 취소 / 환불
223	    // =====================================================================
224	
225	    public OrderResponse cancel(long orderId) {
226	        return tx.execute(status -> {
227	            Order order = orderRepository.findByIdForUpdate(orderId)
228	                    .orElseThrow(() -> new OrderNotFoundException("주문 " + orderId + "을(를) 찾을 수 없습니다."));
229	            Instant now = now();
230	            switch (order.getStatus()) {
231	                case PENDING_PAYMENT -> {
232	                    if (order.isExpiredAt(now)) { // 사실상 EXPIRED: 스케줄러가 곧 전이시킨다
233	                        throw new InvalidOrderStateException("주문 " + orderId + "은(는) 결제 대기 시간이 지났습니다.");
234	                    }
235	                    effects.releaseReservation(order);
236	                    effects.releaseCoupon(order);
237	                    order.cancel(now);
238	                }
239	                case PAID -> {
240	                    if (order.getPaymentId() != null) {
241	                        gateway.refund(order.getPaymentId()); // 장애면 예외 -> 롤백
242	                    }
243	                    effects.restock(order);
244	                    effects.releaseCoupon(order);
245	                    order.refund(now);
246	                }
247	                default -> throw new InvalidOrderStateException(
248	                        "주문 " + orderId + "의 현재 상태(" + order.getStatus() + ")에서는 취소할 수 없습니다.");
249	            }
250	            return OrderResponse.from(order);
251	        });
252	    }
253	
254	    private String json(Object value) {
255	        try {
256	            return objectMapper.writeValueAsString(value);
257	        } catch (JsonProcessingException e) {
258	            throw new IllegalStateException("JSON serialization failed", e);
259	        }
260	    }
261	}
