1	package com.example.order.idempotency;
2	
3	import com.example.order.common.error.IdempotencyInProgressException;
4	import com.example.order.common.error.IdempotencyKeyMismatchException;
5	import com.example.order.idempotency.IdempotencyRepository.Row;
6	import java.time.Clock;
7	import java.time.temporal.ChronoUnit;
8	import java.util.Optional;
9	import org.slf4j.Logger;
10	import org.slf4j.LoggerFactory;
11	import org.springframework.stereotype.Service;
12	
13	/**
14	 * 멱등 키 처리 (01 설계 6.4). 이 서비스는 트랜잭션을 열지 않는다.
15	 * begin()/abandon()은 각자 짧은 autocommit 이고, complete()는 호출자의 비즈니스 트랜잭션에 참여한다.
16	 */
17	@Service
18	public class IdempotencyService {
19	
20	    private static final Logger log = LoggerFactory.getLogger(IdempotencyService.class);
21	    private static final int MAX_ATTEMPTS = 3;
22	
23	    /** replay가 있으면 처리 없이 그대로 응답, 없으면 recordId 소유권을 얻은 것. */
24	    public record Begin(Long recordId, IdempotentResponse replay) {
25	    }
26	
27	    private final IdempotencyRepository repository;
28	    private final Clock clock;
29	
30	    public IdempotencyService(IdempotencyRepository repository, Clock clock) {
31	        this.repository = repository;
32	        this.clock = clock;
33	    }
34	
35	    public Begin begin(IdempotencyScope scope, String key, String fingerprint) {
36	        for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
37	            Optional<Long> inserted = repository.tryInsert(scope, key, fingerprint, clock.instant().truncatedTo(ChronoUnit.MICROS));
38	            if (inserted.isPresent()) {
39	                return new Begin(inserted.get(), null);
40	            }
41	            Optional<Row> existing = repository.find(scope, key);
42	            if (existing.isEmpty()) {
43	                continue; // 그 사이 삭제됨 -> 다시 시도
44	            }
45	            Row row = existing.get();
46	            if (!row.fingerprint().equals(fingerprint)) {
47	                throw new IdempotencyKeyMismatchException("같은 Idempotency-Key로 다른 요청이 전송되었습니다.");
48	            }
49	            if (row.completed()) {
50	                return new Begin(null, new IdempotentResponse(row.responseStatus(), row.responseBody(), row.responseLocation()));
51	            }
52	            throw new IdempotencyInProgressException("같은 Idempotency-Key의 요청이 처리 중입니다.");
53	        }
54	        throw new IdempotencyInProgressException("같은 Idempotency-Key의 요청이 처리 중입니다.");
55	    }
56	
57	    /** 비즈니스 트랜잭션 안에서 호출: 반영과 응답 저장이 원자적이다. */
58	    public void complete(long recordId, IdempotentResponse response) {
59	        int updated = repository.complete(recordId, response.status(), response.body(), response.locationPath(),
60	                clock.instant().truncatedTo(ChronoUnit.MICROS));
61	        if (updated != 1) {
62	            throw new IllegalStateException("idempotency record " + recordId + " is not IN_PROGRESS");
63	        }
64	    }
65	
66	    /** 비2xx로 끝난 요청의 키를 풀어 같은 요청으로 재시도할 수 있게 한다 (R4.4). 트랜잭션 밖에서 호출. */
67	    public void abandon(long recordId) {
68	        try {
69	            repository.deleteInProgress(recordId);
70	        } catch (RuntimeException e) {
71	            log.error("Failed to release idempotency record {}", recordId, e);
72	        }
73	    }
74	}
