1	package com.example.order.idempotency;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.time.Instant;
6	import java.time.OffsetDateTime;
7	import java.time.ZoneOffset;
8	import java.util.List;
9	import java.util.Optional;
10	import org.springframework.jdbc.core.JdbcTemplate;
11	import org.springframework.stereotype.Repository;
12	
13	/** JdbcTemplate 기반. 활성 트랜잭션이 있으면 그 커넥션에 참여한다. */
14	@Repository
15	public class IdempotencyRepository {
16	
17	    public record Row(long id, String fingerprint, String status, Integer responseStatus, String responseBody,
18	            String responseLocation) {
19	        public boolean completed() {
20	            return "COMPLETED".equals(status);
21	        }
22	    }
23	
24	    private final JdbcTemplate jdbc;
25	
26	    public IdempotencyRepository(JdbcTemplate jdbc) {
27	        this.jdbc = jdbc;
28	    }
29	
30	    /** 삽입되면 새 id, 이미 키가 있으면 empty. */
31	    public Optional<Long> tryInsert(IdempotencyScope scope, String key, String fingerprint, Instant now) {
32	        List<Long> ids = jdbc.queryForList("""
33	                INSERT INTO idempotency_records(scope, idempotency_key, request_fingerprint, status, created_at)
34	                VALUES (?, ?, ?, 'IN_PROGRESS', ?)
35	                ON CONFLICT (scope, idempotency_key) DO NOTHING
36	                RETURNING id
37	                """, Long.class, scope.name(), key, fingerprint, OffsetDateTime.ofInstant(now, ZoneOffset.UTC));
38	        return ids.isEmpty() ? Optional.empty() : Optional.of(ids.get(0));
39	    }
40	
41	    public Optional<Row> find(IdempotencyScope scope, String key) {
42	        List<Row> rows = jdbc.query("""
43	                SELECT id, request_fingerprint, status, response_status, response_body, response_location
44	                FROM idempotency_records WHERE scope = ? AND idempotency_key = ?
45	                """, (ResultSet rs, int i) -> mapRow(rs), scope.name(), key);
46	        return rows.stream().findFirst();
47	    }
48	
49	    private static Row mapRow(ResultSet rs) throws SQLException {
50	        int rs0 = rs.getInt("response_status");
51	        Integer responseStatus = rs.wasNull() ? null : rs0;
52	        return new Row(rs.getLong("id"), rs.getString("request_fingerprint"), rs.getString("status"),
53	                responseStatus, rs.getString("response_body"), rs.getString("response_location"));
54	    }
55	
56	    public int complete(long id, int responseStatus, String body, String location, Instant now) {
57	        return jdbc.update("""
58	                UPDATE idempotency_records
59	                SET status = 'COMPLETED', response_status = ?, response_body = ?, response_location = ?, completed_at = ?
60	                WHERE id = ? AND status = 'IN_PROGRESS'
61	                """, responseStatus, body, location, OffsetDateTime.ofInstant(now, ZoneOffset.UTC), id);
62	    }
63	
64	    public int deleteInProgress(long id) {
65	        return jdbc.update("DELETE FROM idempotency_records WHERE id = ? AND status = 'IN_PROGRESS'", id);
66	    }
67	}
