2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	
8	/** 01 설계 6.3: sha256(scope \n POST \n canonicalPath \n (N|U:userId) \n canonicalBody) */
9	public final class RequestFingerprint {
10	
11	    private RequestFingerprint() {
12	    }
13	
14	    public static String of(IdempotencyScope scope, String canonicalPath, String userId, String canonicalBody) {
15	        String raw = scope.name() + "\n" + "POST" + "\n" + canonicalPath + "\n"
16	                + (userId == null ? "N" : "U:" + userId) + "\n" + canonicalBody;
17	        try {
18	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
19	            return HexFormat.of().formatHex(digest);
20	        } catch (NoSuchAlgorithmException e) {
21	            throw new IllegalStateException(e);
22	        }
23	    }
24	}
