68	
69	    protected Order() {
70	    }
71	
72	    public Order(String userId, String couponCode, List<OrderLine> items, long subtotal, long discount,
73	            Instant createdAt, Instant expiresAt) {
74	        this.userId = userId;
75	        this.status = OrderStatus.PENDING_PAYMENT;
76	        this.couponCode = couponCode;
