9	/** 키셋 페이지네이션용 동적 쿼리 (필터가 없으면 조건을 뺀다). */
10	@Repository
11	public class OrderQueryRepository {
12	
13	    @PersistenceContext
14	    private EntityManager em;
15	
16	    /** limit개를 (createdAt desc, id desc) 순으로 읽는다. */
17	    public List<Order> findPage(String userId, OrderStatus status, OrderCursor cursor, int limit) {
18	        StringBuilder jpql = new StringBuilder("select o from Order o where 1 = 1");
19	        if (userId != null) {
20	            jpql.append(" and o.userId = :userId");
21	        }
22	        if (status != null) {
23	            jpql.append(" and o.status = :status");
24	        }
25	        if (cursor != null) {
26	            jpql.append(" and (o.createdAt < :cAt or (o.createdAt = :cAt and o.id < :cId))");
27	        }
28	        jpql.append(" order by o.createdAt desc, o.id desc");
29	        TypedQuery<Order> query = em.createQuery(jpql.toString(), Order.class);
30	        if (userId != null) {
31	            query.setParameter("userId", userId);
32	        }
33	        if (status != null) {
34	            query.setParameter("status", status);
35	        }
36	        if (cursor != null) {
37	            query.setParameter("cAt", cursor.createdAt());
38	            query.setParameter("cId", cursor.id());
39	        }
40	        return query.setMaxResults(limit).getResultList();
41	    }
