1	package com.example.order.ordering;
2	
3	import com.example.order.common.error.RequestValidationException;
4	import java.nio.charset.StandardCharsets;
5	import java.time.Instant;
6	import java.util.Base64;
7	import java.util.regex.Pattern;
8	
9	/** 목록 커서: Base64URL(패딩 없음) of "<createdAt epoch micros>:<id>" (01 설계 9.2) */
10	public record OrderCursor(long createdAtMicros, long id) {
11	
12	    private static final Pattern FORMAT = Pattern.compile("^-?\\d{1,19}:\\d{1,19}$");
13	
14	    public static OrderCursor of(Order order) {
15	        Instant at = order.getCreatedAt();
16	        long micros = Math.addExact(Math.multiplyExact(at.getEpochSecond(), 1_000_000L), at.getNano() / 1000);
17	        return new OrderCursor(micros, order.getId());
18	    }
19	
20	    public String encode() {
21	        return Base64.getUrlEncoder().withoutPadding()
22	                .encodeToString((createdAtMicros + ":" + id).getBytes(StandardCharsets.UTF_8));
23	    }
24	
25	    public Instant createdAt() {
26	        return Instant.ofEpochSecond(Math.floorDiv(createdAtMicros, 1_000_000L),
27	                Math.floorMod(createdAtMicros, 1_000_000L) * 1000L);
28	    }
29	
30	    public static OrderCursor decode(String raw) {
31	        try {
32	            String text = new String(Base64.getUrlDecoder().decode(raw), StandardCharsets.UTF_8);
33	            if (!FORMAT.matcher(text).matches()) {
34	                throw invalid();
35	            }
36	            int sep = text.indexOf(':');
37	            long micros = Long.parseLong(text.substring(0, sep));
38	            long id = Long.parseLong(text.substring(sep + 1));
39	            if (id < 1) {
40	                throw invalid();
41	            }
42	            return new OrderCursor(micros, id);
43	        } catch (IllegalArgumentException e) { // Base64 디코딩 실패, 숫자 오버플로
44	            throw invalid();
45	        }
46	    }
47	
48	    private static RequestValidationException invalid() {
49	        return new RequestValidationException("cursor", "해석할 수 없는 cursor 입니다");
50	    }
51	}
