1	package com.example.order.ordering;
2	
3	import com.example.order.common.error.ProductNotFoundException;
4	import com.example.order.coupon.Coupon;
5	import com.example.order.coupon.CouponRepository;
6	import com.example.order.product.Product;
7	import com.example.order.product.ProductRepository;
8	import java.util.Collection;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.function.Function;
12	import java.util.stream.Collectors;
13	import org.springframework.stereotype.Component;
14	
15	/**
16	 * 주문 상태 전이에 따른 재고/쿠폰 부수 효과 (01 설계 13). 반드시 활성 트랜잭션 안에서,
17	 * 주문 행 락을 먼저 잡은 뒤 호출한다. 락 순서: orders -> products(id 오름차순) -> coupons.
18	 */
19	@Component
20	public class OrderEffects {
21	
22	    private final ProductRepository productRepository;
23	    private final CouponRepository couponRepository;
24	
25	    public OrderEffects(ProductRepository productRepository, CouponRepository couponRepository) {
26	        this.productRepository = productRepository;
27	        this.couponRepository = couponRepository;
28	    }
29	
30	    /** 상품을 id 오름차순으로 FOR UPDATE. 없는 id가 있으면 404. */
31	    public Map<Long, Product> lockProducts(Collection<Long> productIds) {
32	        List<Long> sorted = productIds.stream().distinct().sorted().toList();
33	        Map<Long, Product> byId = productRepository.findAllByIdInForUpdate(sorted).stream()
34	                .collect(Collectors.toMap(Product::getId, Function.identity()));
35	        List<Long> missing = sorted.stream().filter(id -> !byId.containsKey(id)).toList();
36	        if (!missing.isEmpty()) {
37	            throw new ProductNotFoundException("상품을 찾을 수 없습니다: " + missing);
38	        }
39	        return byId;
40	    }
41	
42	    private Map<Long, Product> lockProductsOf(Order order) {
43	        return lockProducts(order.getItems().stream().map(OrderLine::productId).toList());
44	    }
45	
46	    /** 결제 승인: stock -= q, reserved -= q */
47	    public void confirmSale(Order order) {
48	        Map<Long, Product> products = lockProductsOf(order);
49	        order.getItems().forEach(l -> products.get(l.productId()).confirmSale(l.quantity()));
50	    }
51	
52	    /** 예약 해제: reserved -= q (거절/만료/취소) */
53	    public void releaseReservation(Order order) {
54	        Map<Long, Product> products = lockProductsOf(order);
55	        order.getItems().forEach(l -> products.get(l.productId()).releaseReservation(l.quantity()));
56	    }
57	
58	    /** 환불: stock += q */
59	    public void restock(Order order) {
60	        Map<Long, Product> products = lockProductsOf(order);
61	        order.getItems().forEach(l -> products.get(l.productId()).restock(l.quantity()));
62	    }
63	
64	    /** 쿠폰 사용 복원: usedCount -= 1. 상품 락 뒤에 호출한다. */
65	    public void releaseCoupon(Order order) {
66	        if (order.getCouponCode() == null) {
67	            return;
68	        }
69	        Coupon coupon = couponRepository.findByCodeForUpdate(order.getCouponCode())
70	                .orElseThrow(() -> new IllegalStateException("coupon missing for order " + order.getId()));
71	        coupon.release();
72	    }
73	}
