1	package com.example.order.ordering;
2	
3	import com.example.order.common.config.OrderProperties;
4	import java.time.Clock;
5	import java.time.Instant;
6	import java.time.temporal.ChronoUnit;
7	import java.util.List;
8	import org.slf4j.Logger;
9	import org.slf4j.LoggerFactory;
10	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
11	import org.springframework.data.domain.PageRequest;
12	import org.springframework.scheduling.annotation.Scheduled;
13	import org.springframework.stereotype.Component;
14	import org.springframework.transaction.support.TransactionTemplate;
15	
16	/** 결제 대기 만료 (R6). 주문마다 별도 트랜잭션 + SKIP LOCKED (01 설계 8). */
17	@Component
18	@ConditionalOnProperty(name = "order.expiration.enabled", havingValue = "true", matchIfMissing = true)
19	public class OrderExpirationScheduler {
20	
21	    private static final Logger log = LoggerFactory.getLogger(OrderExpirationScheduler.class);
22	
23	    private final OrderRepository orderRepository;
24	    private final OrderEffects effects;
25	    private final OrderProperties properties;
26	    private final Clock clock;
27	    private final TransactionTemplate tx;
28	
29	    public OrderExpirationScheduler(OrderRepository orderRepository, OrderEffects effects,
30	            OrderProperties properties, Clock clock, TransactionTemplate tx) {
31	        this.orderRepository = orderRepository;
32	        this.effects = effects;
33	        this.properties = properties;
34	        this.clock = clock;
35	        this.tx = tx;
36	    }
37	
38	    @Scheduled(fixedDelayString = "${order.expiration.scan-interval-ms:500}")
39	    public void expireOverdueOrders() {
40	        int batch = properties.expiration().batchSize();
41	        try {
42	            while (true) {
43	                Instant now = clock.instant().truncatedTo(ChronoUnit.MICROS);
44	                List<Long> ids = orderRepository.findExpiredIds(OrderStatus.PENDING_PAYMENT, now, PageRequest.of(0, batch));
45	                int expired = 0;
46	                for (Long id : ids) {
47	                    try {
48	                        if (Boolean.TRUE.equals(tx.execute(status -> expireOne(id)))) {
49	                            expired++;
50	                        }
51	                    } catch (RuntimeException e) {
52	                        log.error("Failed to expire order {}", id, e);
53	                    }
54	                }
55	                if (ids.size() < batch || expired == 0) {
56	                    break;
57	                }
58	            }
59	        } catch (RuntimeException e) {
60	            log.error("Order expiration scan failed", e);
61	        }
62	    }
63	
64	    private boolean expireOne(long id) {
65	        // 결제/취소가 처리 중이면 empty -> 다음 회차에 다시 본다
66	        Order order = orderRepository.lockForExpiration(id).orElse(null);
67	        if (order == null) {
68	            return false;
69	        }
70	        Instant now = clock.instant().truncatedTo(ChronoUnit.MICROS);
71	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT || order.getExpiresAt().isAfter(now)) {
72	            return false;
73	        }
74	        effects.releaseReservation(order);
75	        effects.releaseCoupon(order);
76	        order.expire(now);
77	        return true;
78	    }
79	}
