1	package com.example.order.payment;
2	
3	import com.example.order.common.config.PaymentGatewayProperties;
4	import com.fasterxml.jackson.databind.JsonNode;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import java.net.http.HttpClient;
7	import java.util.Map;
8	import org.slf4j.Logger;
9	import org.slf4j.LoggerFactory;
10	import org.springframework.http.MediaType;
11	import org.springframework.http.client.JdkClientHttpRequestFactory;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.client.RestClient;
14	
15	/**
16	 * 외부 PG 클라이언트. HTTP를 모르는 결과 타입만 돌려준다.
17	 * 5xx / 4xx / 연결 실패 / 읽기 타임아웃(기본 2초) / 계약 밖 응답은 모두 PaymentGatewayUnavailableException.
18	 */
19	@Component
20	public class PaymentGatewayClient {
21	
22	    private static final Logger log = LoggerFactory.getLogger(PaymentGatewayClient.class);
23	
24	    // PG 응답은 필드 타입(paymentId가 숫자/문자열)에 관대하게 JsonNode로 읽는다.
25	    private final ObjectMapper lenientMapper = new ObjectMapper();
26	    private final RestClient restClient;
27	
28	    public PaymentGatewayClient(PaymentGatewayProperties properties) {
29	        HttpClient httpClient = HttpClient.newBuilder()
30	                .version(HttpClient.Version.HTTP_1_1)
31	                .connectTimeout(properties.connectTimeout())
32	                .build();
33	        JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(httpClient);
34	        factory.setReadTimeout(properties.readTimeout());
35	        this.restClient = RestClient.builder()
36	                .baseUrl(properties.url().toString())
37	                .requestFactory(factory)
38	                .build();
39	    }
40	
41	    /** POST /v1/payments. idempotencyKey는 클라이언트가 보낸 Idempotency-Key 그대로 (R5.3). */
42	    public PaymentResult pay(String idempotencyKey, long orderId, long amount, String cardToken) {
43	        try {
44	            String body = restClient.post()
45	                    .uri("/v1/payments")
46	                    .contentType(MediaType.APPLICATION_JSON)
47	                    .header("Idempotency-Key", idempotencyKey)
48	                    .body(Map.of("orderId", orderId, "amount", amount, "cardToken", cardToken))
49	                    .retrieve()
50	                    .body(String.class);
51	            JsonNode node = parse(body);
52	            String paymentId = text(node, "paymentId");
53	            String status = text(node, "status");
54	            if (paymentId == null || status == null) {
55	                throw unavailable("PG 응답에 paymentId/status가 없습니다", null);
56	            }
57	            return switch (status) {
58	                case "APPROVED" -> PaymentResult.approved(paymentId);
59	                case "DECLINED" -> PaymentResult.declined(paymentId);
60	                default -> throw unavailable("알 수 없는 PG 결제 상태: " + status, null);
61	            };
62	        } catch (PaymentGatewayUnavailableException e) {
63	            throw e;
64	        } catch (RuntimeException e) {
65	            throw unavailable("PG 결제 요청 실패", e);
66	        }
67	    }
68	
69	    /** POST /v1/payments/{paymentId}/refund. 200 + REFUNDED 외에는 모두 장애. */
70	    public void refund(String paymentId) {
71	        try {
72	            String body = restClient.post()
73	                    .uri("/v1/payments/{paymentId}/refund", paymentId)
74	                    .retrieve()
75	                    .body(String.class);
76	            String status = text(parse(body), "status");
77	            if (!"REFUNDED".equals(status)) {
78	                throw unavailable("알 수 없는 PG 환불 상태: " + status, null);
79	            }
80	        } catch (PaymentGatewayUnavailableException e) {
81	            throw e;
82	        } catch (RuntimeException e) {
83	            throw unavailable("PG 환불 요청 실패", e);
84	        }
85	    }
86	
87	    private JsonNode parse(String body) {
88	        try {
