spring:
  application:
    name: order-service
  datasource:
    # SPRING_DATASOURCE_URL / _USERNAME / _PASSWORD 환경 변수는 Boot relaxed binding으로 자동 우선 적용된다.
    url: jdbc:postgresql://localhost:5432/orders   # 로컬 기본값(임의)
    username: order                                 # 로컬 기본값(임의)
