package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.AbstractIntegrationTest;
import com.example.order.support.ApiResponse;
import java.time.Instant;
import org.junit.jupiter.api.Test;

class ProductCouponSmokeTest extends AbstractIntegrationTest {

    @Test
    void product_createAndGet() {
        ApiResponse created = createProduct("keyboard", 45000, 10);

        assertThat(created.status()).isEqualTo(201);
        assertThat(created.header("Location")).endsWith("/api/products/" + created.id());
        assertThat(created.json().get("reserved").asInt()).isZero();
        assertThat(created.json().get("available").asInt()).isEqualTo(10);

        ApiResponse fetched = getProduct(created.id());
        assertThat(fetched.status()).isEqualTo(200);
        assertThat(fetched.text("name")).isEqualTo("keyboard");
        assertThat(fetched.longValue("price")).isEqualTo(45000);
    }

    @Test
    void product_get_unknown_returns404ProblemDetail() {
        ApiResponse r = getProduct(999_999_999L);

        assertThat(r.status()).isEqualTo(404);
        assertThat(r.code()).isEqualTo("PRODUCT_NOT_FOUND");
    }

    @Test
    void product_create_invalid_returns400ProblemDetail() {
        ApiResponse r = createProduct("bad", 0, 10);

        assertThat(r.status()).isEqualTo(400);
        assertThat(r.contentType()).startsWith("application/problem+json");
        assertThat(r.code()).isEqualTo("VALIDATION_ERROR");
        assertThat(r.text("title")).isNotBlank();
        assertThat(r.text("detail")).isNotBlank();
        assertThat(r.json().get("status").asInt()).isEqualTo(400);
        assertThat(r.text("type")).isNotBlank();
    }

    @Test
    void product_create_malformedJson_returns400() {
        ApiResponse r = postProduct("{\"name\":");

        assertThat(r.status()).isEqualTo(400);
        assertThat(r.contentType()).startsWith("application/problem+json");
        assertThat(r.code()).isEqualTo("VALIDATION_ERROR");
    }

    @Test
    void product_create_wrongTypes_return400() {
        assertThat(postProduct("{\"name\":\"a\",\"price\":\"100\",\"stock\":1}").status()).isEqualTo(400);
        assertThat(postProduct("{\"name\":\"a\",\"price\":100.5,\"stock\":1}").status()).isEqualTo(400);
        assertThat(postProduct("{\"name\":123,\"price\":100,\"stock\":1}").status()).isEqualTo(400);
    }

    @Test
    void product_price_beyondIntRange_isRejectedAsLong() {
        // price 상한은 10,000,000 이므로 int 범위 밖 값은 400 (오버플로 없이)
        assertThat(createProduct("big", 3_000_000_000L, 1).status()).isEqualTo(400);
    }

    @Test
    void coupon_createAndGet() {
        String code = uniqueCouponCode();
        ApiResponse created = postCoupon(couponJson(code, "RATE", 10, 10000, 5000L, 100,
                Instant.parse("2026-01-01T00:00:00Z"), Instant.parse("2099-01-01T00:00:00Z")));

        assertThat(created.status()).isEqualTo(201);
        assertThat(created.header("Location")).endsWith("/api/coupons/" + code);
        assertThat(created.json().get("usedCount").asInt()).isZero();

        ApiResponse fetched = getCoupon(code);
        assertThat(fetched.status()).isEqualTo(200);
        assertThat(fetched.text("type")).isEqualTo("RATE");
        assertThat(fetched.longValue("maxDiscountAmount")).isEqualTo(5000);
        assertThat(Instant.parse(fetched.text("validFrom"))).isEqualTo(Instant.parse("2026-01-01T00:00:00Z"));
    }

    @Test
    void coupon_noMaxDiscount_serializesNull() {
        String code = newCoupon("FIXED", 1000, 0, null, 5);

        ApiResponse fetched = getCoupon(code);
        assertThat(fetched.json().has("maxDiscountAmount")).isTrue();
        assertThat(fetched.json().get("maxDiscountAmount").isNull()).isTrue();
        assertThat(fetched.longValue("minOrderAmount")).isZero();
    }

    @Test
    void coupon_duplicateCode_returns409() {
        String code = newCoupon("FIXED", 1000, 0, null, 5);

        ApiResponse again = postCoupon(couponJson(code, "FIXED", 1000, 0, null, 5));

        assertThat(again.status()).isEqualTo(409);
        assertThat(again.code()).isEqualTo("DUPLICATE_COUPON_CODE");
    }

    @Test
    void coupon_invalid_returns400() {
        // RATE 는 100 초과 불가
        assertThat(postCoupon(couponJson(uniqueCouponCode(), "RATE", 101, 0, null, 5)).status()).isEqualTo(400);
        // 소문자 코드
        assertThat(postCoupon(couponJson("abcd", "FIXED", 100, 0, null, 5)).status()).isEqualTo(400);
        // validFrom >= validUntil
        Instant now = Instant.now();
        assertThat(postCoupon(couponJson(uniqueCouponCode(), "FIXED", 100, 0, null, 5, now, now)).status()).isEqualTo(400);
        // 오프셋 없는 시각
        assertThat(postCoupon("{\"code\":\"" + uniqueCouponCode() + "\",\"type\":\"FIXED\",\"value\":100,"
                + "\"totalQuantity\":5,\"validFrom\":\"2026-01-01T00:00:00\",\"validUntil\":\"2027-01-01T00:00:00\"}")
                .status()).isEqualTo(400);
    }

    @Test
    void coupon_get_unknown_returns404() {
        ApiResponse r = getCoupon("NOPE0000");

        assertThat(r.status()).isEqualTo(404);
        assertThat(r.code()).isEqualTo("COUPON_NOT_FOUND");
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.AbstractIntegrationTest;
import com.example.order.support.ApiResponse;
import java.time.OffsetDateTime;
import org.junit.jupiter.api.Test;

class OrderFlowSmokeTest extends AbstractIntegrationTest {

    @Test
    void happyPath_create_pay_ship_deliver() {
        long productId = newProduct(10_000, 10);

        ApiResponse created = placeOrderOk(productId, 3);
        long orderId = created.id();
        assertThat(created.header("Location")).endsWith("/api/orders/" + orderId);
        assertThat(created.text("status")).isEqualTo("PENDING_PAYMENT");
        assertThat(created.longValue("subtotal")).isEqualTo(30_000);
        assertThat(created.longValue("totalPrice")).isEqualTo(30_000);
        assertThat(created.json().get("paidAt").isNull()).isTrue();
        assertThat(created.json().get("couponCode").isNull()).isTrue();
        assertThat(created.json().get("items").get(0).get("unitPrice").asLong()).isEqualTo(10_000);
        assertThat(OffsetDateTime.parse(created.text("expiresAt")).toInstant())
                .isAfter(OffsetDateTime.parse(created.text("createdAt")).toInstant());

        ApiResponse reserved = getProduct(productId);
        assertThat(reserved.json().get("reserved").asInt()).isEqualTo(3);
        assertThat(reserved.json().get("available").asInt()).isEqualTo(7);

        String payKey = uniqueKey();
        ApiResponse paid = pay(orderId, payKey, "tok_visa");
        assertThat(paid.status()).isEqualTo(200);
        assertThat(paid.text("status")).isEqualTo("PAID");
        assertThat(paid.text("paidAt")).isNotNull();
        assertThat(PG.paymentCalls()).hasSize(1);
        assertThat(PG.paymentCalls().get(0).idempotencyKey()).isEqualTo(payKey);
        assertThat(PG.paymentCalls().get(0).amount()).isEqualTo(30_000);
        assertThat(PG.paymentCalls().get(0).cardToken()).isEqualTo("tok_visa");

        ApiResponse sold = getProduct(productId);
        assertThat(sold.json().get("stock").asInt()).isEqualTo(7);
        assertThat(sold.json().get("reserved").asInt()).isZero();

        assertThat(ship(orderId).text("status")).isEqualTo("SHIPPED");
        assertThat(deliver(orderId).text("status")).isEqualTo("DELIVERED");
        assertThat(getOrder(orderId).text("status")).isEqualTo("DELIVERED");
    }

    @Test
    void ship_beforePay_returns409InvalidState() {
        long orderId = placeOrderOk(newProduct(1000, 5), 1).id();

        ApiResponse r = ship(orderId);

        assertThat(r.status()).isEqualTo(409);
        assertThat(r.code()).isEqualTo("INVALID_STATE");
    }

    @Test
    void create_withCoupon_appliesDiscount_andDeclineRestores() {
        long productId = newProduct(10_000, 10);
        String coupon = newCoupon("RATE", 10, 0, 500L, 3);

        ApiResponse created = placeOrder(coupon, line(productId, 2));
        assertThat(created.status()).isEqualTo(201);
        assertThat(created.longValue("subtotal")).isEqualTo(20_000);
        assertThat(created.longValue("discount")).isEqualTo(500); // 10% = 2000, 상한 500
        assertThat(created.longValue("totalPrice")).isEqualTo(19_500);
        assertThat(getCoupon(coupon).longValue("usedCount")).isEqualTo(1);

        PG.decline();
        ApiResponse declined = pay(created.id());
        assertThat(declined.status()).isEqualTo(402);
        assertThat(declined.contentType()).startsWith("application/problem+json");
        assertThat(declined.code()).isEqualTo("PAYMENT_DECLINED");

        assertThat(getOrder(created.id()).text("status")).isEqualTo("PAYMENT_FAILED");
        assertThat(getProduct(productId).json().get("reserved").asInt()).isZero();
        assertThat(getCoupon(coupon).longValue("usedCount")).isZero();
    }

    @Test
    void pay_gatewayError_returns503_andLeavesStateUntouched() {
        long productId = newProduct(1000, 5);
        long orderId = placeOrderOk(productId, 2).id();

        PG.http500();
        ApiResponse r = pay(orderId);

        assertThat(r.status()).isEqualTo(503);
        assertThat(r.code()).isEqualTo("PAYMENT_GATEWAY_UNAVAILABLE");
        assertThat(getOrder(orderId).text("status")).isEqualTo("PENDING_PAYMENT");
        assertThat(getProduct(productId).json().get("reserved").asInt()).isEqualTo(2);

        // 장애로 끝난 결제는 같은 키로 다시 시도할 수 있다 (R4.4)
        PG.approve();
        assertThat(pay(orderId).status()).isEqualTo(200);
    }

    @Test
    void pay_gatewaySlowerThan2s_returns503() {
        long orderId = placeOrderOk(newProduct(1000, 5), 1).id();

        PG.delayPayment(3000);
        long start = System.nanoTime();
        ApiResponse r = pay(orderId);
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;

        assertThat(r.status()).isEqualTo(503);
        assertThat(elapsedMs).isBetween(1_800L, 2_900L);
        assertThat(getOrder(orderId).text("status")).isEqualTo("PENDING_PAYMENT");
    }

    @Test
    void pay_zeroTotal_skipsGateway() {
        long productId = newProduct(1000, 5);
        String coupon = newCoupon("FIXED", 5000, 0, null, 5); // subtotal 보다 큰 정액 -> 상한 subtotal
        ApiResponse created = placeOrder(coupon, line(productId, 1));
        assertThat(created.longValue("totalPrice")).isZero();

        ApiResponse paid = pay(created.id());

        assertThat(paid.status()).isEqualTo(200);
        assertThat(paid.text("status")).isEqualTo("PAID");
        assertThat(PG.paymentCallCount()).isZero();
    }

    @Test
    void cancel_pending_releasesReservation() {
        long productId = newProduct(1000, 5);
        long orderId = placeOrderOk(productId, 4).id();

        ApiResponse r = cancel(orderId);

        assertThat(r.status()).isEqualTo(200);
        assertThat(r.text("status")).isEqualTo("CANCELLED");
        assertThat(getProduct(productId).json().get("reserved").asInt()).isZero();
        assertThat(cancel(orderId).status()).isEqualTo(409);
    }

    @Test
    void cancel_paid_refundsAndRestocks() {
        long productId = newProduct(1000, 5);
        long orderId = newPaidOrder(productId, 2);
        assertThat(getProduct(productId).json().get("stock").asInt()).isEqualTo(3);

        ApiResponse r = cancel(orderId);

        assertThat(r.status()).isEqualTo(200);
        assertThat(r.text("status")).isEqualTo("REFUNDED");
        assertThat(PG.refundCalls()).hasSize(1);
        assertThat(getProduct(productId).json().get("stock").asInt()).isEqualTo(5);
    }

    @Test
    void cancel_paid_refundFailure_returns503_andKeepsPaid() {
        long productId = newProduct(1000, 5);
        long orderId = newPaidOrder(productId, 2);

        PG.refund500();
        ApiResponse r = cancel(orderId);

        assertThat(r.status()).isEqualTo(503);
        assertThat(getOrder(orderId).text("status")).isEqualTo("PAID");
        assertThat(getProduct(productId).json().get("stock").asInt()).isEqualTo(3);
    }

    @Test
    void create_errors_404_and_409() {
        long productId = newProduct(1000, 2);

        assertThat(placeOrder(null, line(999_999_999L, 1)).code()).isEqualTo("PRODUCT_NOT_FOUND");
        assertThat(placeOrder("NOSUCH99", line(productId, 1)).code()).isEqualTo("COUPON_NOT_FOUND");
        ApiResponse tooMany = placeOrder(null, line(productId, 3));
        assertThat(tooMany.status()).isEqualTo(409);
        assertThat(tooMany.code()).isEqualTo("INSUFFICIENT_STOCK");
        assertThat(getProduct(productId).json().get("reserved").asInt()).isZero();
    }

    @Test
    void create_validation_400() {
        long productId = newProduct(1000, 5);
        String user = uniqueUser();

        assertThat(postOrder(null, uniqueKey(), orderJson(null, line(productId, 1))).status()).isEqualTo(400);
        assertThat(postOrder(user, null, orderJson(null, line(productId, 1))).status()).isEqualTo(400);
        assertThat(postOrder(user, uniqueKey(), orderJson(null, line(productId, 1), line(productId, 2))).status()).isEqualTo(400);
        assertThat(postOrder(user, uniqueKey(), orderJson(null, line(productId, 0))).status()).isEqualTo(400);
        assertThat(postOrder(user, uniqueKey(), "{\"items\":[]}").status()).isEqualTo(400);
        ApiResponse badId = get("/api/orders/abc");
        assertThat(badId.status()).isEqualTo(400);
        assertThat(badId.code()).isEqualTo("VALIDATION_ERROR");
        assertThat(badId.json().get("errors").get(0).get("field").asText()).isEqualTo("id");
        assertThat(listOrders("size=abc").json().get("errors")).isNotEmpty();
        assertThat(getOrder(999_999_999L).code()).isEqualTo("ORDER_NOT_FOUND");
    }

    @Test
    void idempotency_create_replaysSameResponse_andMismatchIs422() {
        long productId = newProduct(1000, 5);
        String user = uniqueUser();
        String key = uniqueKey();
        String body = orderJson(null, line(productId, 2));

        ApiResponse first = postOrder(user, key, body);
        ApiResponse replay = postOrder(user, key, body);

        assertThat(first.status()).isEqualTo(201);
        assertThat(replay.status()).isEqualTo(201);
        assertThat(replay.body()).isEqualTo(first.body());
        assertThat(replay.header("Location")).isEqualTo(first.header("Location"));
        assertThat(getProduct(productId).json().get("reserved").asInt()).isEqualTo(2); // 한 번만 처리

        ApiResponse mismatch = postOrder(user, key, orderJson(null, line(productId, 3)));
        assertThat(mismatch.status()).isEqualTo(422);
        assertThat(mismatch.code()).isEqualTo("IDEMPOTENCY_KEY_MISMATCH");
        assertThat(postOrder(uniqueUser(), key, body).status()).isEqualTo(422); // 다른 사용자
    }

    @Test
    void idempotency_create_errorKeyCanBeRetried() {
        long productId = newProduct(1000, 1);
        String user = uniqueUser();
        String key = uniqueKey();
        String body = orderJson(null, line(productId, 2));

        assertThat(postOrder(user, key, body).status()).isEqualTo(409); // 재고 부족, 키는 저장되지 않음

        // 재고를 늘릴 수단이 없으므로 같은 요청이 다시 같은 오류(처리됨, IN_PROGRESS 아님)를 받는지만 본다
        ApiResponse again = postOrder(user, key, body);
        assertThat(again.status()).isEqualTo(409);
        assertThat(again.code()).isEqualTo("INSUFFICIENT_STOCK");
    }

    @Test
    void idempotency_pay_replaysAndCallsGatewayOnce() {
        long orderId = placeOrderOk(newProduct(1000, 5), 1).id();
        String key = uniqueKey();

        ApiResponse first = pay(orderId, key, "tok_a");
        ApiResponse replay = pay(orderId, key, "tok_a");

        assertThat(first.status()).isEqualTo(200);
        assertThat(replay.status()).isEqualTo(200);
        assertThat(replay.body()).isEqualTo(first.body());
        assertThat(PG.paymentCallCount()).isEqualTo(1);
        assertThat(pay(orderId, key, "tok_other").status()).isEqualTo(422);
        // 키 공간은 엔드포인트별로 독립: 주문 생성에 쓴 키를 결제에 써도 충돌하지 않는다
        String createKey = uniqueKey();
        long productId = newProduct(1000, 5);
        ApiResponse created = postOrder(uniqueUser(), createKey, orderJson(null, line(productId, 1)));
        assertThat(pay(created.id(), createKey, "tok_b").status()).isEqualTo(200);
    }

    @Test
    void pay_missingIdempotencyKey_returns400() {
        long orderId = placeOrderOk(newProduct(1000, 5), 1).id();

        assertThat(postPay(orderId, null, "{\"cardToken\":\"t\"}").status()).isEqualTo(400);
        assertThat(postPay(orderId, uniqueKey(), "{\"cardToken\":\"  \"}").status()).isEqualTo(400);
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.AbstractIntegrationTest;
import com.example.order.support.ApiResponse;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class OrderListSmokeTest extends AbstractIntegrationTest {

    @Test
    void list_cursorPaging_returnsEachOrderExactlyOnce() {
        long productId = newProduct(1000, 100);
        String user = uniqueUser();
        List<Long> created = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            ApiResponse r = postOrder(user, uniqueKey(), orderJson(null, line(productId, 1)));
            assertThat(r.status()).isEqualTo(201);
            created.add(r.id());
        }

        List<Long> seen = new ArrayList<>();
        String cursor = null;
        int pages = 0;
        do {
            ApiResponse page = listOrders("userId=" + user + "&size=2" + (cursor == null ? "" : "&cursor=" + cursor));
            assertThat(page.status()).isEqualTo(200);
            for (JsonNode n : page.json().get("content")) {
                seen.add(n.get("id").asLong());
            }
            JsonNode next = page.json().get("nextCursor");
            cursor = next.isNull() ? null : next.asText();
            if (++pages == 1) {
                // 첫 페이지 이후 새 주문이 생겨도 이어지는 페이지에는 영향이 없다 (R9.5)
                postOrder(user, uniqueKey(), orderJson(null, line(productId, 1)));
            }
        } while (cursor != null);

        assertThat(seen).hasSize(5).doesNotHaveDuplicates().containsExactlyInAnyOrderElementsOf(created);
        assertThat(seen).isSortedAccordingTo(java.util.Comparator.reverseOrder()); // createdAt desc, id desc
        assertThat(pages).isEqualTo(3);
    }

    @Test
    void list_filters_andValidation() {
        long productId = newProduct(1000, 100);
        String user = uniqueUser();
        long orderId = postOrder(user, uniqueKey(), orderJson(null, line(productId, 1))).id();
        postOrder(user, uniqueKey(), orderJson(null, line(productId, 1)));
        cancel(orderId);

        ApiResponse cancelled = listOrders("userId=" + user + "&status=CANCELLED");
        assertThat(cancelled.json().get("content")).hasSize(1);
        assertThat(cancelled.json().get("nextCursor").isNull()).isTrue();

        assertThat(listOrders("status=BOGUS").status()).isEqualTo(400);
        assertThat(listOrders("size=0").status()).isEqualTo(400);
        assertThat(listOrders("size=101").status()).isEqualTo(400);
        assertThat(listOrders("size=abc").status()).isEqualTo(400);
        assertThat(listOrders("cursor=not-a-cursor!!").status()).isEqualTo(400);
        assertThat(listOrders("userId=" + uniqueUser()).json().get("content")).isEmpty();
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.AbstractIntegrationTest;
import com.example.order.support.ApiResponse;
import java.util.List;
import org.junit.jupiter.api.Test;

class OrderConcurrencySmokeTest extends AbstractIntegrationTest {

    @Test
    void stock_20concurrentOrders_exactly10succeed() {
        long productId = newProduct(1000, 10);

        List<ApiResponse> results = runConcurrently(20, i -> placeOrder(null, line(productId, 1)));

        assertThat(countStatus(results, 201)).isEqualTo(10);
        assertThat(countStatus(results, 409)).isEqualTo(10);
        assertThat(getProduct(productId).json().get("reserved").asInt()).isEqualTo(10);
    }

    @Test
    void coupon_15usersFor5Quantity_exactly5succeed() {
        long productId = newProduct(1000, 100);
        String coupon = newCoupon("FIXED", 100, 0, null, 5);

        List<ApiResponse> results = runConcurrently(15, i -> placeOrder(coupon, line(productId, 1)));

        assertThat(countStatus(results, 201)).isEqualTo(5);
        assertThat(countStatus(results, 409)).isEqualTo(10);
        assertThat(results.stream().filter(r -> r.status() == 409).map(ApiResponse::code))
                .allMatch("COUPON_EXHAUSTED"::equals);
        assertThat(getCoupon(coupon).longValue("usedCount")).isEqualTo(5);
        assertThat(getProduct(productId).json().get("reserved").asInt()).isEqualTo(5); // 실패한 주문은 예약을 남기지 않는다
    }

    @Test
    void coupon_sameUserFiveConcurrentOrders_exactlyOneSucceeds() {
        long productId = newProduct(1000, 100);
        String coupon = newCoupon("FIXED", 100, 0, null, 50);
        String user = uniqueUser();

        List<ApiResponse> results = runConcurrently(5,
                i -> postOrder(user, uniqueKey(), orderJson(coupon, line(productId, 1))));

        assertThat(countStatus(results, 201)).isEqualTo(1);
        assertThat(countStatus(results, 409)).isEqualTo(4);
        assertThat(getCoupon(coupon).longValue("usedCount")).isEqualTo(1);
    }

    @Test
    void lockOrder_mixedProductOrder_noDeadlock_andReservedIsExact() {
        long p = newProduct(1000, 1000);
        long q = newProduct(1000, 1000);

        List<ApiResponse> results = runConcurrently(20, i -> i % 2 == 0
                ? placeOrder(null, line(p, 1), line(q, 1))
                : placeOrder(null, line(q, 1), line(p, 1)));

        assertThat(results).allMatch(r -> r.status() == 201, "all created without 5xx");
        assertThat(getProduct(p).json().get("reserved").asInt()).isEqualTo(20);
        assertThat(getProduct(q).json().get("reserved").asInt()).isEqualTo(20);
    }

    @Test
    void pay_concurrentOnSameOrder_callsGatewayOnce_andOneSuccess() {
        long productId = newProduct(1000, 10);
        long orderId = placeOrderOk(productId, 1).id();

        List<ApiResponse> results = runConcurrently(8, i -> pay(orderId));

        assertThat(countStatus(results, 200)).isEqualTo(1);
        assertThat(countStatus(results, 409)).isEqualTo(7);
        assertThat(PG.paymentCallsForOrder(orderId)).hasSize(1);
        assertThat(getProduct(productId).json().get("stock").asInt()).isEqualTo(9);
    }

    @Test
    void idempotency_sameKeyConcurrent_processedOnce() {
        long productId = newProduct(1000, 100);
        String user = uniqueUser();
        String key = uniqueKey();
        String body = orderJson(null, line(productId, 1));

        List<ApiResponse> results = runConcurrently(10, i -> postOrder(user, key, body));

        assertThat(results).allMatch(r -> r.status() == 201 || r.status() == 409);
        assertThat(countStatus(results, 201)).isGreaterThanOrEqualTo(1);
        assertThat(results.stream().filter(r -> r.status() == 201).map(ApiResponse::body).distinct()).hasSize(1);
        assertThat(getProduct(productId).json().get("reserved").asInt()).isEqualTo(1);
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.ApiResponse;
import com.example.order.support.IntegrationTestSupport;
import java.time.Duration;
import java.time.Instant;
import java.time.OffsetDateTime;
import org.junit.jupiter.api.Test;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;

/** 짧은 TTL(PT2S) 컨텍스트 예시: IntegrationTestSupport를 직접 상속해 프로퍼티 조합을 바꾼다. */
class OrderExpirationSmokeTest extends IntegrationTestSupport {

    @DynamicPropertySource
    static void properties(DynamicPropertyRegistry registry) {
        registry.add("payment.gateway.url", PG::baseUrl);
        registry.add("order.payment-ttl", () -> "PT2S");
    }

    @Test
    void pendingOrder_expiresWithin2Seconds_andRestoresReservationAndCoupon() throws Exception {
        long productId = newProduct(1000, 10);
        String coupon = newCoupon("FIXED", 100, 0, null, 3);
        ApiResponse created = placeOrder(coupon, line(productId, 4));
        assertThat(created.status()).isEqualTo(201);
        Instant expiresAt = OffsetDateTime.parse(created.text("expiresAt")).toInstant();
        assertThat(Duration.between(OffsetDateTime.parse(created.text("createdAt")).toInstant(), expiresAt))
                .isEqualTo(Duration.ofSeconds(2));

        long sleepMs = Duration.between(Instant.now(), expiresAt.plusSeconds(2)).toMillis();
        if (sleepMs > 0) {
            Thread.sleep(sleepMs);
        }

        assertThat(getOrder(created.id()).text("status")).isEqualTo("EXPIRED");
        assertThat(getProduct(productId).json().get("reserved").asInt()).isZero();
        assertThat(getCoupon(coupon).longValue("usedCount")).isZero();
    }

    @Test
    void pay_afterExpiry_returns409InvalidState() throws Exception {
        long orderId = placeOrderOk(newProduct(1000, 10), 1).id();

        awaitOrderStatus(orderId, "EXPIRED", Duration.ofSeconds(6));
        ApiResponse r = pay(orderId);

        assertThat(r.status()).isEqualTo(409);
        assertThat(r.code()).isEqualTo("INVALID_STATE");
        assertThat(PG.paymentCallCount()).isZero();
    }
}

package com.example.order.common.error;

import com.example.order.common.error.RequestValidationException.FieldIssue;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.ConstraintViolationException;
import java.net.URI;
import java.util.ArrayList;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.TypeMismatchException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.MediaType;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.FieldError;
import org.springframework.validation.ObjectError;
import org.springframework.web.HttpMediaTypeNotSupportedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.MissingServletRequestParameterException;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.ServletWebRequest;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.method.annotation.HandlerMethodValidationException;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

/** RFC 9457 Problem Details. 모든 오류 응답은 application/problem+json + code 필드를 갖는다. */
@RestControllerAdvice
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    // ---- 도메인 예외 ----

    @ExceptionHandler(BusinessException.class)
    ResponseEntity<Object> handleBusiness(BusinessException ex, HttpServletRequest request) {
        List<FieldIssue> errors = ex instanceof RequestValidationException rve ? rve.getErrors() : List.of();
        return problem(ex.getCode().status(), ex.getCode(), ex.getMessage(), HttpHeaders.EMPTY, request.getRequestURI(), errors);
    }

    @ExceptionHandler(ConstraintViolationException.class)
    ResponseEntity<Object> handleConstraintViolation(ConstraintViolationException ex, HttpServletRequest request) {
        List<FieldIssue> errors = ex.getConstraintViolations().stream()
                .map(v -> new FieldIssue(v.getPropertyPath().toString(), v.getMessage()))
                .toList();
        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 값이 올바르지 않습니다",
                HttpHeaders.EMPTY, request.getRequestURI(), errors);
    }

    @ExceptionHandler(DataIntegrityViolationException.class)
    ResponseEntity<Object> handleDataIntegrity(DataIntegrityViolationException ex, HttpServletRequest request) {
        String chain = causeMessages(ex);
        String uri = request.getRequestURI();
        if (chain.contains("uk_coupons_code")) {
            return businessProblem(ErrorCode.DUPLICATE_COUPON_CODE, "이미 존재하는 쿠폰 코드입니다", uri);
        }
        if (chain.contains("ux_orders_active_coupon_user")) {
            return businessProblem(ErrorCode.COUPON_NOT_APPLICABLE, "이미 이 쿠폰을 사용 중인 주문이 있습니다", uri);
        }
        if (chain.contains("ck_products_reserved_range")) {
            return businessProblem(ErrorCode.INSUFFICIENT_STOCK, "주문 가능 수량이 부족합니다", uri);
        }
        if (chain.contains("ck_coupons_used_count")) {
            return businessProblem(ErrorCode.COUPON_EXHAUSTED, "쿠폰이 모두 소진되었습니다", uri);
        }
        log.error("Unmapped data integrity violation", ex);
        return internal(uri);
    }

    @ExceptionHandler(Exception.class)
    ResponseEntity<Object> handleUnexpected(Exception ex, HttpServletRequest request) {
        log.error("Unexpected error on {}", request.getRequestURI(), ex);
        return internal(request.getRequestURI());
    }

    // ---- 프레임워크(MVC) 예외: 모두 code를 붙인다 ----

    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
        List<FieldIssue> errors = new ArrayList<>();
        for (FieldError fe : ex.getBindingResult().getFieldErrors()) {
            errors.add(new FieldIssue(fe.getField(), fe.getDefaultMessage()));
        }
        for (ObjectError oe : ex.getBindingResult().getGlobalErrors()) {
            errors.add(new FieldIssue(oe.getObjectName(), oe.getDefaultMessage()));
        }
        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 값이 올바르지 않습니다",
                headers, path(request), errors);
    }

    @Override
    protected ResponseEntity<Object> handleHandlerMethodValidationException(HandlerMethodValidationException ex,
            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
        List<FieldIssue> errors = new ArrayList<>();
        ex.getParameterValidationResults().forEach(r -> r.getResolvableErrors().forEach(e ->
                errors.add(new FieldIssue(String.valueOf(r.getMethodParameter().getParameterName()), e.getDefaultMessage()))));
        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 값이 올바르지 않습니다",
                headers, path(request), errors);
    }

    @Override
    protected ResponseEntity<Object> handleHttpMessageNotReadable(HttpMessageNotReadableException ex,
            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "요청 본문을 해석할 수 없습니다",
                headers, path(request), List.of(new FieldIssue("body", "올바른 JSON 형식과 타입이어야 합니다")));
    }

    /** 415는 R11.3 표 밖이므로 400으로 매핑한다 (01 설계 11.2). */
    @Override
    protected ResponseEntity<Object> handleHttpMediaTypeNotSupported(HttpMediaTypeNotSupportedException ex,
            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
        return problem(HttpStatus.BAD_REQUEST, ErrorCode.VALIDATION_ERROR, "지원하지 않는 Content-Type 입니다",
                HttpHeaders.EMPTY, path(request), List.of(new FieldIssue("header:Content-Type", "application/json 이어야 합니다")));
    }

    @Override
    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, Object body, HttpHeaders headers,
            HttpStatusCode statusCode, WebRequest request) {
        HttpStatus status = HttpStatus.resolve(statusCode.value());
        ErrorCode code = status == null ? ErrorCode.INTERNAL_ERROR : switch (status) {
            case BAD_REQUEST -> ErrorCode.VALIDATION_ERROR;
            case NOT_FOUND -> ErrorCode.RESOURCE_NOT_FOUND;
            case METHOD_NOT_ALLOWED -> ErrorCode.METHOD_NOT_ALLOWED;
            case NOT_ACCEPTABLE -> ErrorCode.NOT_ACCEPTABLE;
            default -> statusCode.is4xxClientError() ? ErrorCode.VALIDATION_ERROR : ErrorCode.INTERNAL_ERROR;
        };
        if (code == ErrorCode.INTERNAL_ERROR) {
            log.error("Framework error", ex);
            return internal(path(request));
        }
        String detail = body instanceof ProblemDetail pd && pd.getDetail() != null ? pd.getDetail() : code.title();
        List<FieldIssue> errors = code == ErrorCode.VALIDATION_ERROR ? frameworkIssues(ex) : List.of();
        return problem(statusCode, code, detail, headers, path(request), errors);
    }

    /** 프레임워크가 던진 400에도 errors[]를 1건 이상 채운다 (01 설계 11.1). */
    private static List<FieldIssue> frameworkIssues(Exception ex) {
        if (ex instanceof MethodArgumentTypeMismatchException m) {
            String prefix = m.getParameter().hasParameterAnnotation(RequestParam.class) ? "query:" : "";
            return List.of(new FieldIssue(prefix + m.getName(), "값의 형식이 올바르지 않습니다"));
        }
        if (ex instanceof TypeMismatchException t) {
            return List.of(new FieldIssue(String.valueOf(t.getPropertyName()), "값의 형식이 올바르지 않습니다"));
        }
        if (ex instanceof MissingRequestHeaderException h) {
            return List.of(new FieldIssue("header:" + h.getHeaderName(), "필수 헤더가 없습니다"));
        }
        if (ex instanceof MissingServletRequestParameterException q) {
            return List.of(new FieldIssue("query:" + q.getParameterName(), "필수 파라미터가 없습니다"));
        }
        return List.of(new FieldIssue("request", "요청이 올바르지 않습니다"));
    }

    // ---- 조립 ----

    private ResponseEntity<Object> businessProblem(ErrorCode code, String detail, String uri) {
        return problem(code.status(), code, detail, HttpHeaders.EMPTY, uri, List.of());
    }

    private ResponseEntity<Object> internal(String uri) {
        return problem(HttpStatus.INTERNAL_SERVER_ERROR, ErrorCode.INTERNAL_ERROR,
                "서버 내부 오류가 발생했습니다", HttpHeaders.EMPTY, uri, List.of());
    }

    private ResponseEntity<Object> problem(HttpStatusCode status, ErrorCode code, String detail, HttpHeaders headers,
            String uri, List<FieldIssue> errors) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
        pd.setType(URI.create(code.typeUri()));
        pd.setTitle(code.title());
        pd.setProperty("code", code.name());
        if (uri != null) {
            try {
                pd.setInstance(URI.create(uri));
            } catch (IllegalArgumentException ignored) {
                // instance는 선택 필드
            }
        }
        if (errors != null && !errors.isEmpty()) {
            pd.setProperty("errors", errors);
        }
        HttpHeaders out = new HttpHeaders();
        if (headers != null) {
            out.putAll(headers);
        }
        out.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
        return new ResponseEntity<>(pd, out, status);
    }

    private static String path(WebRequest request) {
        return request instanceof ServletWebRequest swr ? swr.getRequest().getRequestURI() : null;
    }

    private static String causeMessages(Throwable ex) {
        StringBuilder sb = new StringBuilder();
        for (Throwable t = ex; t != null; t = t.getCause()) {
            if (t.getMessage() != null) {
                sb.append(t.getMessage()).append('\n');
            }
            if (t.getCause() == t) {
                break;
            }
        }
        return sb.toString();
    }
}
package com.example.order.ordering;

import com.example.order.common.error.RequestValidationException;
import com.example.order.common.web.RequestHeaders;
import com.example.order.idempotency.IdempotentResponse;
import com.example.order.ordering.dto.CreateOrderRequest;
import com.example.order.ordering.dto.OrderPageResponse;
import com.example.order.ordering.dto.OrderResponse;
import com.example.order.ordering.dto.PayRequest;
import jakarta.validation.Valid;
import java.net.URI;
import java.util.HashSet;
import java.util.Set;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.support.ServletUriComponentsBuilder;

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderService orderService;
    private final OrderCommandService commandService;

    public OrderController(OrderService orderService, OrderCommandService commandService) {
        this.orderService = orderService;
        this.commandService = commandService;
    }

    @PostMapping
    public ResponseEntity<String> create(
            @RequestHeader(value = RequestHeaders.USER_ID, required = false) String userId,
            @RequestHeader(value = RequestHeaders.IDEMPOTENCY_KEY, required = false) String idempotencyKey,
            @Valid @RequestBody CreateOrderRequest request) {
        RequestHeaders.requireUserId(userId);
        RequestHeaders.requireIdempotencyKey(idempotencyKey);
        rejectDuplicateProducts(request);
        if (request.couponCode() != null && request.couponCode().isBlank()) {
            throw new RequestValidationException("couponCode", "공백만으로 된 값은 사용할 수 없습니다");
        }
        return toResponse(commandService.create(userId, idempotencyKey, request));
    }

    @GetMapping("/{id}")
    public OrderResponse get(@PathVariable long id) {
        return orderService.get(id);
    }

    @GetMapping
    public OrderPageResponse list(
            @RequestParam(required = false) String userId,
            @RequestParam(required = false) String status,
            @RequestParam(required = false) String size,
            @RequestParam(required = false) String cursor) {
        if (userId != null && (userId.isBlank() || userId.length() > 50)) {
            throw new RequestValidationException("query:userId", "공백이 아닌 1~50자여야 합니다");
        }
        OrderStatus statusFilter = null;
        if (status != null) {
            try {
                statusFilter = OrderStatus.valueOf(status);
            } catch (IllegalArgumentException e) {
                throw new RequestValidationException("query:status", "정의되지 않은 상태입니다: " + status);
            }
        }
        int pageSize = 20;
        if (size != null) {
            try {
                pageSize = Integer.parseInt(size);
            } catch (NumberFormatException e) {
                throw new RequestValidationException("query:size", "정수여야 합니다");
            }
            if (pageSize < 1 || pageSize > 100) {
                throw new RequestValidationException("query:size", "1~100 이어야 합니다");
            }
        }
        OrderCursor decoded = cursor == null ? null : OrderCursor.decode(cursor);
        return orderService.list(userId, statusFilter, pageSize, decoded);
    }

    @PostMapping("/{id}/pay")
    public ResponseEntity<String> pay(
            @PathVariable long id,
            @RequestHeader(value = RequestHeaders.USER_ID, required = false) String userId,
            @RequestHeader(value = RequestHeaders.IDEMPOTENCY_KEY, required = false) String idempotencyKey,
            @Valid @RequestBody PayRequest request) {
        RequestHeaders.requireIdempotencyKey(idempotencyKey);
        return toResponse(commandService.pay(id, idempotencyKey, userId, request));
    }

    @PostMapping("/{id}/cancel")
    public OrderResponse cancel(@PathVariable long id) {
        return commandService.cancel(id);
    }

    @PostMapping("/{id}/ship")
    public OrderResponse ship(@PathVariable long id) {
        return orderService.ship(id);
    }

    @PostMapping("/{id}/deliver")
    public OrderResponse deliver(@PathVariable long id) {
        return orderService.deliver(id);
    }

    private static void rejectDuplicateProducts(CreateOrderRequest request) {
        Set<Long> seen = new HashSet<>();
        for (CreateOrderRequest.Item item : request.items()) {
            if (!seen.add(item.productId())) {
                throw new RequestValidationException("items", "같은 productId를 중복해서 주문할 수 없습니다: " + item.productId());
            }
        }
    }

    /** 최초 응답과 재생 응답을 같은 경로로 내보낸다: 저장된 JSON 원문 그대로. */
    private static ResponseEntity<String> toResponse(IdempotentResponse r) {
        ResponseEntity.BodyBuilder builder = ResponseEntity.status(r.status()).contentType(MediaType.APPLICATION_JSON);
        if (r.locationPath() != null) {
            URI location = ServletUriComponentsBuilder.fromCurrentContextPath().path(r.locationPath()).build().toUri();
            builder.location(location);
        }
        return builder.body(r.body());
    }
}
