    void c3_pay_replayBeatsConflict_newKeyGetsConflict() {
        long orderId = placeOrderOk(newProduct(1_000, 5), 1).id();
        String key = uniqueKey();
        ApiResponse first = pay(orderId, key, "tok");

        ApiResponse replay = pay(orderId, key, "tok");
