    @Test
    @DisplayName("R7.3 PG 환불이 2초 안에 응답하지 않으면(지연 3000ms) 약 2초 뒤 503이고 주문·재고·쿠폰은 바뀌지 않는다")
    void r7_3_refundTimeout_returns503_andLeavesStateUntouched() {
        long productId = newProduct(1_000, 10);
